package com.project7.localmanager;
import java.io.*;import java.nio.file.*;import java.lang.reflect.*;import java.util.*;import android.content.*;import android.content.res.*;
public final class StoryMissionHost {
 static void check(boolean b,String m){if(!b)throw new AssertionError(m);}
 static byte[]doc(byte[]p,String k){byte[]d=BsonLite.documentValue(p,k);return d==null?BsonLite.EMPTY_DOCUMENT:d;}
 static Object invoke(Object o,String name,Class<?>[]types,Object...args)throws Exception{Method m=o.getClass().getDeclaredMethod(name,types);m.setAccessible(true);return m.invoke(o,args);}
 public static void main(String[]args)throws Exception{
  File assets=new File(args[0]);Context context=new Context(assets,new AssetManager(assets));LocalTutorialStore.Progress p=LocalTutorialStore.Progress.fresh();p.initPrologue=false;p.inEmergency=false;p.patrolActions=24;p.completedEvents.addAll(Arrays.asList(1013,1043));
  byte[]profile=BsonLite.withAccountIdentity(Files.readAllBytes(new File(assets,"new_player.bson").toPath()),"host_story_missions",900101);profile=BsonLite.withProfileDocument(profile,"weeknum",BsonLite.document("w",3,"d",0,"av",0));profile=BsonLite.withProfileDocument(profile,"std",BsonLite.document("rt","27","ff",false));
  check(StoryMissionBridge.area(4129)==LocalCityProgress.area(4129),"unprepared stock delegate");StoryMissionBridge.prepare(context);check(StoryMissionBridge.area(4129)==5,"source mission area");check(StoryMissionBridge.area(101)==LocalCityProgress.area(101),"unmatched area delegate");
  for(int scene:new int[]{315,316,426,427,428}){int hero=scene<400?14:10;check(StoryMissionBridge.partyAllowed(BsonLite.document("t",2,"s",scene,"h",Arrays.asList(hero))),"default source party");check(!StoryMissionBridge.partyAllowed(BsonLite.document("t",2,"s",scene,"h",Arrays.asList(2))),"wrong source party");check(!StoryMissionBridge.partyAllowed(BsonLite.document("t",2,"s",scene,"h",Collections.emptyList())),"empty source party");check(!StoryMissionBridge.partyAllowed(BsonLite.document("t",1,"s",scene,"h",Arrays.asList(hero))),"wrong wire type");}
  check(StoryMissionBridge.partyAllowed(BsonLite.document("t",1,"s",4129,"h",Arrays.asList(10),"d",BsonLite.document("a",5))),"source stage area");check(!StoryMissionBridge.partyAllowed(BsonLite.document("t",1,"s",4129,"h",Arrays.asList(10),"d",BsonLite.document("a",4))),"wrong stage area rejected");
  LocalCombatCatalog c=new LocalCombatCatalog(context);Method combat=BsonLite.class.getDeclaredMethod("combatDataDocument",Iterable.class,String.class,byte[].class,LocalCombatCatalog.class,int.class,int.class,int.class);combat.setAccessible(true);
  for(int scene:new int[]{315,316,426,427,428}){int hero=scene<400?14:10;byte[]before=profile;byte[]empty=(byte[])combat.invoke(null,Arrays.asList(hero),"synthetic",profile,c,1,scene,2);byte[]owned=BsonLite.withHero(profile,hero);owned=BsonLite.withHeroDocument(owned,hero,BsonLite.document("sl",1,"so",1,"cf",17));byte[]rich=(byte[])combat.invoke(null,Arrays.asList(hero),"synthetic",owned,c,99,scene,2);byte[]first=BsonLite.documentValue(doc(empty,"heroes"),"('synthetic', "+hero+")"),second=BsonLite.documentValue(doc(rich,"heroes"),"('synthetic', "+hero+")");check(Arrays.equals(first,c.missionHero(scene,hero))&&Arrays.equals(first,second),"actual BsonLite uses same fixed source MH owned/unowned "+scene);check(BsonLite.intValue(first,"lv")== (scene<400?60:100),"fixed source actor level");check(c.missionLevel(scene,"adjust_hero_lv",1)==(scene<400?60:100),"fixed MC hero lv");check(c.storyMonsterLevel(scene,3)==(scene<400?1:100),"source SM+explicit MC monster lv");check(Arrays.equals(before,profile),"source profile unchanged");}
  LocalEventCatalog graph=new LocalEventCatalog(new FileInputStream(new File(assets,"event_graph.tsv")));LocalNewbeeCatalog nb=new LocalNewbeeCatalog(new ByteArrayInputStream(new byte[0]));
  for(int[]pair:new int[][]{{1342,426},{1343,427},{1344,428},{7144,315},{7157,316}}){LocalTutorialStore.Progress ep=LocalTutorialStore.Progress.fresh();ep.initPrologue=false;ep.inEmergency=false;LocalEventEngine engine=new LocalEventEngine(graph,nb,ep,0,profile,true);ep.processingEvents.clear();ep.processingEvents.add(pair[0]);check(engine.beginStoryBattle(pair[1])&&engine.hasPendingStoryBattle(pair[1]),"original processing/pending trial owner");check(!engine.beginStoryBattle(999999),"no source owner");}
  p.eventConditions.put("battle",new HashSet<>(Arrays.asList(101,1101,1102,1103,1104,1105,1106,2101,2102,2103,2104,2105,2106,3101,3102,3103,3104,3105,3106,2119,2114,2115,2116,2117,2118)));byte[]stages=StoryMissionBridge.stages(p,5,profile);check(Integer.valueOf(4129).equals(BsonLite.intValue(stages,"cs")),"source initial4129 "+BsonLite.messagePackValue(stages,false)+" oldstatus="+LocalCityProgress.status(p,5,profile));
  byte[]locked=BsonLite.withProfileInt(profile,"q7ChapterMenu",11);locked=BsonLite.withProfileDocument(locked,"q7ChapterLocks",BsonLite.document("5",true));check(BsonLite.keys(StoryMissionBridge.stages(p,5,locked)).isEmpty(),"original locked gate retained");
  check(Arrays.equals(StoryMissionBridge.stages(p,5,BsonLite.withProfileDocument(profile,"std",BsonLite.document("rt","1"))),LocalCityProgress.stages(p,5,BsonLite.withProfileDocument(profile,"std",BsonLite.document("rt","1")))),"unmatched route delegates");
  System.out.println("PASS original BsonLite MH reply fixed owned/unowned levels/source monster source; original trial pending owner; source chapter initial cs, exact route and unprepared delegates");
 }
}
